# Generated by manage.py generate_test_cases.
import json
from urllib.parse import parse_qs, urlsplit

from bs4 import BeautifulSoup
from django.http import HttpResponse
from django.urls import reverse

from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures


class TestAlignCalendarsComponent(InboxCalendarFixtures, BloomerpComponentTestCase):
    """Tests function `align_calendars` from `bloomerp/components/communication/calendar/align.py`."""

    view_name = "components_calendar_align"

    def extendedSetup(self) -> None:
        """Create owned and shared inboxes for alignment and delegation checks."""
        self.prepare_calendar()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        kwargs = {"inbox_id": self.source.pk}
        return [
            RequestScenario(
                name="Apply persists private selections per inbox",
                view_name="components_calendar_align",
                method="POST",
                user=self.actor,
                view_kwargs=kwargs,
                query_params={"q": "meeting", "calendar_page": "2"},
                data={
                    "selection": json.dumps(
                        {
                            "inboxes": [str(self.source.pk)],
                            "users": [str(self.owner.pk)],
                        }
                    )
                },
                expected=ExpectedResult(response_validators=self.selection_saved),
            ),
            RequestScenario(
                name="Forged calendar selections are denied",
                view_name="components_calendar_align",
                method="POST",
                user=self.actor,
                view_kwargs=kwargs,
                content_type="application/json",
                data={"inboxes": [str(self.other_inbox.pk)], "users": []},
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Unreadable users cannot be selected for calendars",
                view_name="components_calendar_align",
                method="POST",
                user=self.owner,
                view_kwargs=kwargs,
                content_type="application/json",
                data={
                    "inboxes": [str(self.source.pk)],
                    "users": [str(self.outsider.pk)],
                },
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Alignment requires login",
                method="POST",
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Alignment rejects GET",
                user=self.actor,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=405),
            ),
            RequestScenario(
                name="Alignment rejects malformed input",
                method="POST",
                user=self.actor,
                view_kwargs=kwargs,
                data={"selection": "invalid"},
                expected=ExpectedResult(status_code=400),
            ),
        ]

    def selection_saved(self, response: HttpResponse) -> bool:
        """Return a hidden-filter loader retaining the saved scope, fresh token, and navigation parameters."""
        from bloomerp.communication.calendar.access import calendar_overlay_selection
        from bloomerp.permissions.definition import PermissionToken

        saved = calendar_overlay_selection(self.actor, self.source.pk)
        loader = BeautifulSoup(response.content, "html.parser").select_one('[hx-trigger="load"]')
        self.assertIsNotNone(loader)
        query = parse_qs(urlsplit(loader["hx-get"]).query)
        grant = PermissionToken.verify(query["_permission_token"][0], audience=str(self.actor.pk))
        restored = self.client.get(
            reverse("inbox_calendar", kwargs={"inbox_id": self.source.pk})
        )
        filters = json.loads(restored.context["calendar_filters"]["filter"])
        self.assertEqual(
            saved, {"inboxes": [str(self.source.pk)], "users": [str(self.owner.pk)]}
        )
        from bloomerp.communication.utils.permissions import accessible_inboxes

        expected = {str(self.source.pk)} | {
            str(pk)
            for pk in accessible_inboxes(self.owner).values_list("pk", flat=True)
        }
        self.assertEqual(
            set(grant.rule.row_permissions[0].conditions[0].value), expected
        )
        self.assertEqual(set(filters[0]["conditions"][0]["value"]), expected)
        self.assertEqual(set(query["_arg_hide_filters"]), {"true"})
        self.assertEqual(query["_arg_calendar_inbox"], [str(self.source.pk)])
        self.assertEqual(query["cancelled"], ["false"])
        self.assertEqual(query["calendar_color_field"], ["inboxes"])
        self.assertEqual(set(query["calendar_color_values"][0].split(",")), expected)
        self.assertEqual(query["calendar_color_preferred"], [str(self.source.pk)])
        self.assertEqual(query["q"], ["meeting"])
        self.assertEqual(query["calendar_page"], ["2"])
        self.assertEqual(set(json.loads(query["filter"][0])[0]["conditions"][0]["value"]), expected)
        return True
